<script setup lang="ts">
import {provideInputContext} from './inputAssistance'
import {computed,ref,watch} from 'vue'
import {api,post,type Task} from './api'
const props=defineProps<{task?:Task;language?:string;media?:HTMLMediaElement;pageId?:number|null}>()
type Feedback={status?:string;resolutionNote?:string;id:string;rating:number|null;categories:string[];comment:string;page:number|null;playbackSeconds:number|null;createdAt:string;language?:string|null;taskSnapshot?:{name?:string}|null}
const options=[['translation','翻译'],['narration','讲稿'],['speech','语音'],['avatar','数字人'],['subtitles','字幕'],['layout','排版'],['performance','速度或任务处理'],['account','账号或使用问题'],['other','其他']]
const names=Object.fromEntries(options)
const rating=ref(0),categories=ref<string[]>([]),comment=ref(''),positionPage=ref<number|string>(''),positionSeconds=ref<number|null>(null)
const busy=ref(false),loading=ref(false),error=ref(''),message=ref(''),history=ref<Feedback[]>([])
const maxPage=computed(()=>Number((props.task?.outputs?.s1 as any)?.pageCount)||undefined)
let requestId=0
async function load(){const id=++requestId;loading.value=true;try{const rows=await api<Feedback[]>('/v1/feedback'+(props.task?'?taskId='+encodeURIComponent(props.task.id):''));if(id===requestId)history.value=props.language?rows.filter(row=>row.language===props.language):rows}catch(e){if(id===requestId)error.value=(e as Error).message}finally{if(id===requestId)loading.value=false}}
watch([()=>props.task?.id,()=>props.language],()=>{rating.value=0;categories.value=[];comment.value='';positionPage.value='';positionSeconds.value=null;error.value='';message.value='';history.value=[];void load()},{immediate:true})
function capturePosition(){if(props.media&&Number.isFinite(props.media.currentTime))positionSeconds.value=Math.round(props.media.currentTime*1000)/1000;if(props.pageId)positionPage.value=props.pageId}
function clock(seconds:number){return `${Math.floor(seconds/60)}:${Math.floor(seconds%60).toString().padStart(2,'0')}`}
function date(value:string){return new Date(value).toLocaleString()}
async function submit(){error.value='';message.value='';if(!rating.value&&!comment.value.trim()){error.value='请选择评分或填写反馈内容。';return}busy.value=true;try{const value:Record<string,unknown>={rating:rating.value||null,categories:[...categories.value],comment:comment.value.trim()};if(props.task){value.taskId=props.task.id;if(props.language)value.language=props.language;if(positionPage.value!=='')value.page=Number(positionPage.value);if(positionSeconds.value!==null)value.playbackSeconds=positionSeconds.value}await post('/v1/feedback',value);message.value='反馈已保存，谢谢。';rating.value=0;categories.value=[];comment.value='';positionPage.value='';positionSeconds.value=null;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
provideInputContext(()=>({courseId:props.task?.id,page:Number(positionPage.value)||props.pageId||undefined,language:props.language||'zh-CN',context:{problemTypes:categories.value,reportedIssue:comment.value,playbackSeconds:positionSeconds.value}}))
</script>
<template>
 <section class="course-feedback">
  <h3>{{task?'结果评分与反馈':'使用反馈'}}</h3>
  <p class="feedback-intro">{{task?'评价当前课程结果，帮助我们改进生成质量。':'描述使用过程中遇到的问题或建议。'}}</p>
  <form @submit.prevent="submit">
   <fieldset><legend>{{task?'结果评分':'整体体验评分'}}（选填）</legend><div class="rating-options" role="radiogroup" aria-label="评分"><button v-for="score in 5" :key="score" type="button" role="radio" :aria-label="score+' 分'" :aria-checked="rating===score" :class="{selected:rating>=score}" @click="rating=score">★</button><span>{{rating?rating+' / 5':'尚未评分'}}</span><button v-if="rating" type="button" class="text-action" @click="rating=0">清除</button></div><small>1 分：很不满意；5 分：很满意。</small></fieldset>
   <fieldset><legend>问题类型（可多选）</legend><div class="feedback-categories"><label v-for="[key,label] in options" :key="key"><input v-model="categories" type="checkbox" :value="key">{{label}}</label></div></fieldset>
   <label class="comment-label">问题或建议<AssistedTextarea v-model="comment" rows="4" maxlength="4000" placeholder="例如：第 3 页漏译了一句话，或某处语音与字幕不一致。" assist-label="问题或建议" assist-purpose="feedback"></AssistedTextarea></label>
   <div v-if="task" class="feedback-position"><label>相关页码（选填）<input v-model="positionPage" type="number" min="1" :max="maxPage" step="1" placeholder="页码"></label><button v-if="media" type="button" class="secondary-action" @click="capturePosition">记录当前播放位置</button><span v-if="positionSeconds!==null">已记录 {{clock(positionSeconds)}}</span></div>
   <p v-if="error" class="feedback-error" role="alert">{{error}}</p><p v-if="message" class="feedback-success" role="status">{{message}}</p>
   <button class="submit-feedback" type="submit" :disabled="busy">{{busy?'正在提交…':'提交反馈'}}</button>
  </form>
  <details class="feedback-history"><summary>我的反馈（{{history.length}}）</summary><p v-if="loading">正在读取…</p><p v-else-if="!history.length">尚未提交反馈。</p><article v-for="row in history" :key="row.id"><div><strong>{{row.rating?row.rating+' / 5 分':'文字反馈'}}</strong><time>{{date(row.createdAt)}}</time></div><p v-if="!task&&row.taskSnapshot?.name">课程：{{row.taskSnapshot.name}}</p><p v-if="row.categories.length">{{row.categories.map(key=>names[key]||key).join('、')}}</p><p v-if="row.page||row.playbackSeconds!==null">{{row.page?'第 '+row.page+' 页':''}} {{row.playbackSeconds!==null?clock(row.playbackSeconds):''}}</p><p class="saved-comment">{{row.comment}}</p><p v-if="row.status">处理状态：{{({new:'待处理',reviewing:'处理中',planned:'已安排',resolved:'已解决'} as Record<string,string>)[row.status]||row.status}}</p><p v-if="row.resolutionNote">处理说明：{{row.resolutionNote}}</p></article></details>
 </section>
</template>
<style scoped>
.course-feedback{background:#fff;border:1px solid #dce7e0;border-radius:12px;padding:20px;margin:20px 0;color:#173c2c}.course-feedback h3{margin:0 0 6px}.feedback-intro,small{color:#627b6b}.feedback-intro{margin:0 0 16px}.course-feedback fieldset{border:0;padding:0;margin:0 0 18px;min-width:0}.course-feedback legend,.comment-label{font-weight:600;margin-bottom:8px}.rating-options{display:flex;align-items:center;flex-wrap:wrap;gap:5px}.rating-options button{background:none;border:0;color:#c0cbc4;font-size:30px;cursor:pointer;padding:2px}.rating-options button.selected{color:#c3871c}.rating-options span{margin:0 8px;font-size:13px;color:#627b6b}.rating-options .text-action{font-size:13px;color:#277252}.feedback-categories{display:flex;flex-wrap:wrap;gap:9px 18px}.feedback-categories label{display:flex;gap:6px;align-items:center;font-size:14px;font-weight:400;cursor:pointer}.feedback-categories input{accent-color:#24774e}.comment-label{display:block}textarea{display:block;width:100%;box-sizing:border-box;border:1px solid #bdcec3;border-radius:8px;padding:10px;font:inherit;line-height:1.6;margin-top:8px;resize:vertical}.feedback-position{display:flex;flex-wrap:wrap;gap:10px;align-items:end;margin:14px 0}.feedback-position label{font-size:13px}.feedback-position input{display:block;width:100px;padding:8px;margin-top:5px;border:1px solid #bdcec3;border-radius:6px;font:inherit}.secondary-action,.submit-feedback{border:1px solid #286b4d;border-radius:7px;padding:9px 14px;background:#fff;color:#245b42;font:inherit;cursor:pointer}.submit-feedback{background:#246b49;color:#fff;margin-top:10px}.submit-feedback:disabled{opacity:.6;cursor:wait}.feedback-position span{font-size:13px;color:#627b6b}.feedback-error{color:#a22f2f}.feedback-success{color:#1b6d45}.feedback-history{margin-top:20px;border-top:1px solid #dce7e0;padding-top:14px}.feedback-history summary{cursor:pointer}.feedback-history article{border-top:1px solid #e9eeeb;padding:12px 0}.feedback-history article:first-of-type{margin-top:12px}.feedback-history article>div{display:flex;flex-wrap:wrap;justify-content:space-between;gap:8px}.feedback-history time,.feedback-history p{font-size:13px;color:#627b6b;margin:6px 0}.saved-comment{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:600px){.course-feedback{padding:16px}.feedback-categories{gap:12px}.rating-options button{font-size:32px}}
</style>
